update accounting_instr
set actg_sts = #{accountingInstrDO.actgSts,jdbcType=CHAR},
  actg_prc_cd = #{accountingInstrDO.actgPrcCd,jdbcType=CHAR},
  actg_prc_inf = #{accountingInstrDO.actgPrcInf,jdbcType=CHAR},
       actg_dt  = #{accountingInstrDO.actgDt,jdbcType=CHAR},
    gmt_modified = now(3)
where trans_id     = #{accountingInstrDO.transId,jdbcType=VARCHAR}
  and partition_time = #{accountingInstrDO.partitionTime,jdbcType=TIMESTAMP}
  and actg_sts         = #{orgnlActgSts, jdbcType=CHAR}

update accounting_instr
set actg_sts = #{actgSts,jdbcType=CHAR},
    actg_prc_cd = #{actgPrcCd,jdbcType=CHAR},
    actg_prc_inf = #{actgPrcInf,jdbcType=CHAR},
    actg_dt    = #{actgDt,jdbcType=CHAR},
    gmt_modified = #{gmtModified,jdbcType=TIMESTAMP}
where trans_id     = #{transId,jdbcType=VARCHAR}
  and partition_time = #{partitionTime,jdbcType=TIMESTAMP}
